/**
 * Renderiza un template con datos dinámicos.
 * @param {string} template - La cadena del template.
 * @param {Object} data - El objeto de contexto con los datos.
 * @param {Object} options - Opciones adicionales (customHelpers, strictMode, preserveWhitespace).
 * @returns {string} - El HTML o texto renderizado.
 */
function renderTemplate(template, data = {}, options = {}) {
    const {
        customHelpers = {},
        strictMode = false,
        preserveWhitespace = false
    } = options;

    // --- 1. Definición de Helpers y Utilidades ---
    const defaultHelpers = {
        // Helper de debugging
        debug: (...args) => {
            console.log('DEBUG:', args);
            return args[0];
        },

        // Helpers de formato
        uppercase: (str) => String(str).toUpperCase(),
        lowercase: (str) => String(str).toLowerCase(),
        capitalize: (str) => {
            const s = String(str);
            return s.charAt(0).toUpperCase() + s.slice(1);
        },
        date: (date, format) => {
            const d = new Date(date);
            if (isNaN(d.getTime())) return String(date);
            if (format === 'short') return d.toLocaleDateString('es-ES');
            if (format === 'long') return d.toLocaleDateString('es-ES', {
                weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
            });
            return d.toLocaleDateString('es-ES');
        },

        // Helpers Numéricos
        toFixed: (num, digits) => {
            const n = Number(num);
            return isNaN(n) ? num : n.toFixed(digits || 2);
        },
        currency: (num, currencyCode = 'EUR', locale = 'es-ES') => {
            const n = Number(num);
            if (isNaN(n)) return num;
            return new Intl.NumberFormat(locale, {
                style: 'currency',
                currency: currencyCode
            }).format(n);
        },
        number: (num, decimals = 2, locale = 'es-ES') => {
            const n = Number(num);
            if (isNaN(n)) return num;
            return new Intl.NumberFormat(locale, {
                minimumFractionDigits: decimals,
                maximumFractionDigits: decimals
            }).format(n);
        },
        percent: (num, decimals = 0, locale = 'es-ES') => {
            const n = Number(num);
            if (isNaN(n)) return num;
            return new Intl.NumberFormat(locale, {
                style: 'percent',
                minimumFractionDigits: decimals,
                maximumFractionDigits: decimals
            }).format(n / 100);
        },
        abs: (num) => Math.abs(Number(num)),
        round: (num) => Math.round(Number(num)),
        ceil: (num) => Math.ceil(Number(num)),
        floor: (num) => Math.floor(Number(num)),
        padStart: (val, length, char) => String(val).padStart(length, char || '0'),

        // Helpers de comparación
        eq: (a, b) => {
            // Normalizar valores para comparación
            const normA = typeof a === 'string' ? a.replace(/&quot;|&#34;|&#034;/g, '"').replace(/&#39;|&#039;/g, "'") : a;
            const normB = typeof b === 'string' ? b.replace(/&quot;|&#34;|&#034;/g, '"').replace(/&#39;|&#039;/g, "'") : b;
            return normA === normB;
        },
        ne: (a, b) => {
            // Normalizar valores para comparación
            const normA = typeof a === 'string' ? a.replace(/&quot;|&#34;|&#034;/g, '"').replace(/&#39;|&#039;/g, "'") : a;
            const normB = typeof b === 'string' ? b.replace(/&quot;|&#34;|&#034;/g, '"').replace(/&#39;|&#039;/g, "'") : b;
            return normA !== normB;
        },
        gt: (a, b) => Number(a) > Number(b),
        gte: (a, b) => Number(a) >= Number(b),
        lt: (a, b) => Number(a) < Number(b),
        lte: (a, b) => Number(a) <= Number(b),

        // Helpers lógicos
        and: (...args) => args.every(Boolean),
        or: (...args) => args.some(Boolean),
        not: (a) => !a,

        // Helpers de utilidad
        join: (arr, separator = ', ') => {
            if (!Array.isArray(arr)) return String(arr);
            return arr.join(separator);
        },
        getInitialBalanceForRange: (movements, reportStartDate) => {
            if (!Array.isArray(movements) || movements.length === 0) return 0;
            if (!reportStartDate) return movements[0]?.running_balance - movements[0]?.amount || 0;

            const startDate = new Date(reportStartDate);
            const firstMovementInRange = movements.find(m => new Date(m.created_at) >= startDate);

            if (!firstMovementInRange) return 0;
            return firstMovementInRange.running_balance - firstMovementInRange.amount;
        },
        length: (arr) => Array.isArray(arr) ? arr.length : 0,
        default: (value, defaultValue) => value ?? defaultValue,
        json: (obj) => JSON.stringify(obj, null, 2),
        trim: (str) => String(str).trim(),
        contains: (str, search) => String(str).includes(search),
        last: (arr) => Array.isArray(arr) && arr.length > 0 ? arr[arr.length - 1] : null,
        first: (arr) => Array.isArray(arr) && arr.length > 0 ? arr[0] : null,
        lastProp: (pathWithProp, context) => {
            if (!pathWithProp || !context) return null;
            const parts = pathWithProp.split('.');
            let current = context;
            for (let i = 0; i < parts.length; i++) {
                const part = parts[i];
                if (current == null) return null;
                if (part === 'length') {
                    current = Array.isArray(current) ? current.length : null;
                } else if (Array.isArray(current) && /^\d+$/.test(part)) {
                    current = current[parseInt(part, 10)];
                } else {
                    current = current[part];
                }
            }
            if (Array.isArray(current) && current.length > 0) {
                return current[current.length - 1];
            }
            return current;
        },
        getLastBalance: (currencyKey, context) => {
            if (!context || !context.history_by_currency) return null;
            const arr = context.history_by_currency[currencyKey];
            if (!Array.isArray(arr) || arr.length === 0) return null;
            const lastItem = arr[arr.length - 1];
            return lastItem && lastItem.running_balance != null ? lastItem.running_balance : null;
        },
        lastUsdBalance: (usdArray) => {
            if (!Array.isArray(usdArray) || usdArray.length === 0) return null;
            return usdArray[usdArray.length - 1]?.running_balance ?? null;
        },
        lastUyuBalance: (uyuArray) => {
            if (!Array.isArray(uyuArray) || uyuArray.length === 0) return null;
            return uyuArray[uyuArray.length - 1]?.running_balance ?? null;
        },
        isUsdBalancePositive: (usdArray) => {
            if (!Array.isArray(usdArray) || usdArray.length === 0) return false;
            const balance = usdArray[usdArray.length - 1]?.running_balance ?? 0;
            return balance >= 0;
        },
        isUyuBalancePositive: (uyuArray) => {
            if (!Array.isArray(uyuArray) || uyuArray.length === 0) return false;
            const balance = uyuArray[uyuArray.length - 1]?.running_balance ?? 0;
            return balance >= 0;
        },
        formatUsdBalance: (usdObj) => {
            if (!usdObj || !Array.isArray(usdObj.movements) || usdObj.movements.length === 0) return '';
            const movements = usdObj.movements;
            const balance = movements[movements.length - 1]?.running_balance ?? 0;
            const formatted = new Intl.NumberFormat('es-ES', {
                minimumFractionDigits: 2,
                maximumFractionDigits: 2
            }).format(Math.abs(balance));
            const color = balance >= 0 ? '#059669' : '#dc2626';
            return `<p style="font-size:13px;line-height:24px;font-weight:700;color:${color};margin:0;margin-top:0;margin-bottom:0;margin-left:0;margin-right:0">${formatted}</p>`;
        },
        formatUyuBalance: (uyuObj) => {
            if (!uyuObj || !Array.isArray(uyuObj.movements) || uyuObj.movements.length === 0) return '';
            const movements = uyuObj.movements;
            const balance = movements[movements.length - 1]?.running_balance ?? 0;
            const formatted = new Intl.NumberFormat('es-ES', {
                minimumFractionDigits: 2,
                maximumFractionDigits: 2
            }).format(Math.abs(balance));
            const color = balance >= 0 ? '#059669' : '#dc2626';
            return `<p style="font-size:13px;line-height:24px;font-weight:700;color:${color};margin:0;margin-top:0;margin-bottom:0;margin-left:0;margin-right:0">${formatted}</p>`;
        },
        formatDateRange: (startDate, endDate) => {
            const formatDate = (d) => {
                if (!d) return '';
                const date = new Date(d);
                if (isNaN(date.getTime())) return d;
                return date.toLocaleDateString('es-ES');
            };

            let text = 'Período: ';

            if (startDate && endDate) {
                text += `${formatDate(startDate)} al ${formatDate(endDate)}`;
            } else if (startDate) {
                text += `Desde ${formatDate(startDate)}`;
            } else if (endDate) {
                text += `Hasta ${formatDate(endDate)}`;
            } else {
                text += 'Histórico';
            }

            return `<p style="font-size:13px;line-height:24px;color:#4a5568;margin:0 0 8px;margin-top:0;margin-right:0;margin-bottom:8px;margin-left:0">${text}</p>`;
        },

        // Helpers matemáticos
        add: (a, b) => Number(a) + Number(b),
        subtract: (a, b) => Number(a) - Number(b),
        multiply: (a, b) => Number(a) * Number(b),
        divide: (a, b) => Number(a) / Number(b),
        mod: (a, b) => Number(a) % Number(b),
    };

    const helpers = { ...defaultHelpers, ...customHelpers };

    const escapeMap = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#039;'
    };

    // --- 2. Funciones Internas de Procesamiento ---
    const escapeHtml = (text) => {
        return String(text).replace(/[&<>"']/g, m => escapeMap[m]);
    };

    const getValue = (path, context) => {
        if (path === 'this' || path === '.') {
            return (context && context._this_ !== undefined) ? context._this_ : context;
        }

        if (context == null) return undefined;

        let lookupPath = path;
        if (lookupPath.startsWith('this.')) {
            lookupPath = lookupPath.slice(5);
        }

        // Manejo especial para variables especiales de loop (@key, @index, etc.)
        if (lookupPath.startsWith('@')) {
            return context[lookupPath];
        }

        const keys = lookupPath.split('.');
        let current = context;

        for (const key of keys) {
            if (current == null) return undefined;
            // Soporte para índices de array
            if (/^\d+$/.test(key)) {
                current = current[parseInt(key, 10)];
            } else {
                if (current[key] === undefined && current._this_ !== undefined) {
                    current = current._this_;
                }
                current = current[key];
            }
        }
        return current;
    };

    const parseArguments = (argsStr, context) => {
        const args = [];
        // Normalizar las comillas HTML escapadas antes de parsear
        const normalizedStr = argsStr
            .replace(/&quot;/g, '"')
            .replace(/&#39;/g, "'")
            .replace(/&#034;/g, '"')
            .replace(/&#039;/g, "'");

        const argRegex = /"([^"]*)"|'([^']*)'|true|false|null|undefined|(-?\d+\.?\d*)|([a-zA-Z_@][\w.@]*)/g;
        let match;

        while ((match = argRegex.exec(normalizedStr)) !== null) {
            if (match[1] !== undefined) args.push(match[1]); // Comillas dobles
            else if (match[2] !== undefined) args.push(match[2]); // Comillas simples
            else if (match[0] === 'true') args.push(true);
            else if (match[0] === 'false') args.push(false);
            else if (match[0] === 'null') args.push(null);
            else if (match[0] === 'undefined') args.push(undefined);
            else if (match[3] !== undefined) args.push(parseFloat(match[3]));
            else if (match[4] !== undefined) args.push(getValue(match[4], context));
        }
        return args;
    };

    const evaluateHelper = (expression, context) => {
        // Normalizar comillas HTML escapadas
        const normalizedExpr = expression
            .replace(/&quot;/g, '"')
            .replace(/&#39;/g, "'")
            .replace(/&#034;/g, '"')
            .replace(/&#039;/g, "'");

        const helperMatch = normalizedExpr.match(/^\((\w+)\s*(.*?)\)$/);

        if (helperMatch) {
            const [, helperName, argsStr] = helperMatch;
            const helper = helpers[helperName];

            if (!helper) {
                if (strictMode) throw new Error(`Helper "${helperName}" no encontrado`);
                console.warn(`Helper "${helperName}" no encontrado`);
                return false;
            }

            const args = parseArguments(argsStr, context);
            const result = helper(...args);

            return result;
        }

        return getValue(normalizedExpr, context);
    };

    const isTruthy = (value) => {
        if (value == null) return false;
        if (typeof value === 'boolean') return value;
        if (typeof value === 'number') return value !== 0;
        if (typeof value === 'string') return value.length > 0;
        if (Array.isArray(value)) return value.length > 0;
        if (typeof value === 'object') return Object.keys(value).length > 0;
        return Boolean(value);
    };

    // --- 3. Lógica Principal de Parseo ---
    const processContent = (content, context) => {
        let result = content;

        // Función auxiliar para encontrar el endif correspondiente (maneja anidamiento)
        const findMatchingEndif = (str, startIdx) => {
            let depth = 1;
            let i = startIdx;
            let result = -1;
            while (i < str.length && depth > 0) {
                const remaining = str.slice(i);
                // Match various forms of {{#if ...}}
                if (remaining.startsWith('{{#if ') || remaining.startsWith('{{#if') || remaining.startsWith('{{#elseif') || remaining.startsWith('{{#unless') || remaining.startsWith('{{#each')) {
                    depth++;
                    i += 4;
                } else if (remaining.startsWith('{{/if}}') || remaining.startsWith('{{/unless}}') || remaining.startsWith('{{/each}}')) {
                    depth--;
                    if (depth === 0) {
                        result = i;
                        break;
                    }
                    i += 7;
                } else {
                    i++;
                }
            }
            return result;
        };

        // Función para encontrar el {{#if más externo y su {{/if}} correspondiente
        const findOutermostIf = (str) => {
            // Encontrar el {{#if más externo (a nivel 0 de anidamiento)
            let depth = 0;
            let outermostIfStart = -1;
            let outermostCondition = '';

            // Escaneo simple para encontrar el {{#if que no está dentro de otro
            const regex = /\{\{#if\s+(.+?)\}\}/g;
            let match;

            while ((match = regex.exec(str)) !== null) {
                const potentialStart = match.index;

                // Contar cuántos {{#if hay antes de esta posición
                const beforeStr = str.substring(0, potentialStart);
                const openCount = (beforeStr.match(/\{\{#if\s+/g) || []).length;
                const closeCount = (beforeStr.match(/\{\{\/if\}\}/g) || []).length;

                // Si está balanceado (mismos if que endif), es un if de nivel superior
                if (openCount === closeCount) {
                    // Verificar si hay algún {{#if que venga después que esté más hacia afuera
                    // El primero que encontremos que cumpla esta condición es el más externo
                    const remaining = str.substring(potentialStart);
                    const remainingIfs = (remaining.match(/\{\{#if\s+/g) || []).length;

                    if (outermostIfStart === -1 || remainingIfs === 0) {
                        outermostIfStart = potentialStart;
                        outermostCondition = match[1];
                    }
                }
            }

            if (outermostIfStart < 0) return null;

            // Ahora encontrar el {{/if}} correspondiente
            const bodyStart = outermostIfStart + str.substring(outermostIfStart).match(/^\{\{#if\s+.+?\}\}/)[0].length;
            const bodyEnd = findMatchingEndif(str, bodyStart);

            if (bodyEnd < 0) return null;

            return { ifStart: outermostIfStart, condition: outermostCondition, bodyStart, bodyEnd };
        };

        // Función para procesar un bloque if individual
        const processIfBlock = (str, ifStart, condition, bodyStart, bodyEnd) => {
            const body = str.substring(bodyStart, bodyEnd);
            const endifEnd = bodyEnd + 7;

            // Buscar else/elseif en el body (solo los que están al mismo nivel, no anidados)
            const elseifRegex = /\{\{elseif\s+(.+?)\}\}/g;
            const elseRegex = /\{\{else\}\}/g;

            // Encontrar la posición del else/elseif más externos
            const elseMatch = elseRegex.exec(body);
            const elseifMatches = [];
            let elseifMatch;
            while ((elseifMatch = elseifRegex.exec(body)) !== null) {
                elseifMatches.push(elseifMatch);
            }

            // Ordenar y encontrar el primer else/elseif al nivel exterior
            const markers = [];
            if (elseMatch) markers.push({ type: 'else', index: elseMatch.index });
            for (const m of elseifMatches) {
                markers.push({ type: 'elseif', index: m.index, condition: m[1].trim() });
            }
            markers.sort((a, b) => a.index - b.index);

            // Evaluar las secciones
            let rendered = '';
            let foundTruthy = false;

            // Sección if (solo contenido hasta el primer else/elseif)
            const ifContent = markers.length > 0 ? body.substring(0, markers[0].index) : body;
            const ifValue = evaluateHelper(condition.trim(), context);
            if (isTruthy(ifValue)) {
                rendered = processContent(ifContent, context);
                foundTruthy = true;
            }

            // Secciones elseif/else
            if (!foundTruthy) {
                for (let i = 0; i < markers.length; i++) {
                    const marker = markers[i];
                    const nextMarker = markers[i + 1];
                    const startIdx = body.indexOf('}}', marker.index) + 2;
                    const endIdx = nextMarker ? nextMarker.index : body.length;
                    const sectionContent = body.substring(startIdx, endIdx);

                    if (marker.type === 'else') {
                        rendered = processContent(sectionContent, context);
                        break;
                    } else if (marker.type === 'elseif') {
                        const elseifValue = evaluateHelper(marker.condition, context);
                        if (isTruthy(elseifValue)) {
                            rendered = processContent(sectionContent, context);
                            break;
                        }
                    }
                }
            }

            return { start: ifStart, end: endifEnd, rendered };
        };

        // 3.1 Condicionales - procesar de afuera hacia adentro
        let maxIterations = 100;
        let iterations = 0;

        while (iterations < maxIterations) {
            iterations++;
            const outermostIf = findOutermostIf(result);
            if (!outermostIf) break;

            const processed = processIfBlock(result, outermostIf.ifStart, outermostIf.condition, outermostIf.bodyStart, outermostIf.bodyEnd);
            result = result.substring(0, processed.start) + processed.rendered + result.substring(processed.end);
        }

        // 3.2 Unless
        result = result.replace(
            /\{\{#unless\s+(.+?)\}\}([\s\S]*?)\{\{\/unless\}\}/g,
            (match, condition, innerContent) => {
                const value = evaluateHelper(condition.trim(), context);
                return !isTruthy(value) ? processContent(innerContent, context) : '';
            }
        );

        // 3.3 Helpers standalone (operaciones matemáticas, etc.)
        result = result.replace(
            /\{\{\((\w+)(?:\s+(.+?))?\)\|(\w+)(?:\s+([^}]+))?\}\}/g,
            (match, helperName, helperArgs, pipeHelperName, pipeHelperArgs) => {
                const helper = helpers[helperName];
                const pipeHelper = helpers[pipeHelperName];

                if (!helper) {
                    if (strictMode) throw new Error(`Helper "${helperName}" no encontrado`);
                    console.warn(`Helper "${helperName}" no encontrado`);
                    return '';
                }

                const args = helperArgs
                    ? parseArguments(helperArgs, context)
                    : [];
                const firstResult = helper(...args);

                if (!pipeHelper) {
                    return firstResult !== undefined ? escapeHtml(firstResult) : '';
                }

                const pipeArgs = pipeHelperArgs
                    ? [firstResult, ...parseArguments(pipeHelperArgs, context)]
                    : [firstResult];
                const finalResult = pipeHelper(...pipeArgs);
                return finalResult !== undefined ? escapeHtml(finalResult) : '';
            }
        );

        // 3.3b Helpers standalone without pipe
        result = result.replace(
            /\{\{\((\w+)(?:\s+(.+?))?\)\}\}/g,
            (match, helperName, helperArgs) => {
                const helper = helpers[helperName];

                if (!helper) {
                    if (strictMode) throw new Error(`Helper "${helperName}" no encontrado`);
                    console.warn(`Helper "${helperName}" no encontrado`);
                    return '';
                }

                const args = helperArgs
                    ? parseArguments(helperArgs, context)
                    : [];
                const res = helper(...args);
                return res !== undefined ? escapeHtml(res) : '';
            }
        );

        // 3.4 Variables con helpers (soporta encadenamiento: {{var|h1|h2 args}})
        result = result.replace(
            /\{\{([\w.@]+|this\.[\w.]+)((?:\|\w+(?:\s+[^|{}]+)?)+)\}\}/g,
            (match, path, pipesStr) => {
                let value = getValue(path, context);

                const segments = pipesStr.slice(1).split('|');
                for (const segment of segments) {
                    const trimmed = segment.trim();
                    const spaceIdx = trimmed.indexOf(' ');
                    const helperName = spaceIdx === -1 ? trimmed : trimmed.slice(0, spaceIdx);
                    const helperArgs = spaceIdx === -1 ? '' : trimmed.slice(spaceIdx + 1);

                    const helper = helpers[helperName];
                    if (!helper) {
                        if (strictMode) throw new Error(`Helper "${helperName}" no encontrado`);
                        console.warn(`Helper "${helperName}" no encontrado`);
                        continue;
                    }

                    const args = helperArgs
                        ? [value, ...parseArguments(helperArgs, context)]
                        : [value];
                    value = helper(...args);
                }

                return value !== undefined ? escapeHtml(value) : '';
            }
        );

        // 3.5 Variables sin escapar {{{ }}} (simple paths)
        result = result.replace(/\{\{\{([\w.@]+|this\.[\w.]+)\}\}\}/g, (match, path) => {
            const value = getValue(path, context);
            return value !== undefined ? String(value) : '';
        });

        // 3.5b Helpers sin escapar {{{helperName args}}}
        result = result.replace(/\{\{\{(\w+)\s+([\s\S]*?)\}\}\}/g, (match, helperName, helperArgs) => {
            const helper = helpers[helperName];
            if (!helper) {
                if (strictMode) throw new Error(`Helper "${helperName}" no encontrado`);
                console.warn(`Helper "${helperName}" no encontrado`);
                return '';
            }
            // Clean up helperArgs - normalize whitespace first
            const cleanArgs = helperArgs.replace(/\\s+/g, ' ').trim();
            const args = cleanArgs
                ? parseArguments(cleanArgs, context)
                : [];
            const res = helper(...args);
            return res !== undefined ? String(res) : '';
        });

        // 3.6 Variables escapadas {{ }}
        result = result.replace(/\{\{(?!#|\/|elseif|else(?!\w)|\()([\w.@]+|this\.[\w.]+)\}\}/g, (match, path) => {
            const value = getValue(path, context);
            return value !== undefined ? escapeHtml(value) : '';
        });

        return result;
    };

    const processLoops = (tmpl, dataCtx) => {
        return tmpl.replace(
            /\{\{#each ([\w.]+)(?:\s+as\s+\|(\w+)(?:\s*,\s*(\w+))?\|)?\}\}([\s\S]*?)\{\{\/each\}\}/g,
            (match, key, itemAlias, indexAlias, content) => {
                const collection = getValue(key, dataCtx);

                let items = [];

                if (Array.isArray(collection)) {
                    if (collection.length === 0) return '';
                    items = collection.map((item, index) => ({
                        _this_: item,
                        '@index': index,
                        '@first': index === 0,
                        '@last': index === collection.length - 1,
                        '@odd': index % 2 === 1,
                        '@even': index % 2 === 0,
                        '@length': collection.length
                    }));
                } else if (typeof collection === 'object' && collection !== null) {
                    const keys = Object.keys(collection);
                    if (keys.length === 0) return '';
                    items = keys.map((key, index) => ({
                        _this_: collection[key],
                        '@key': key,
                        '@index': index,
                        '@first': index === 0,
                        '@last': index === keys.length - 1,
                        '@odd': index % 2 === 1,
                        '@even': index % 2 === 0,
                        '@length': keys.length
                    }));
                } else {
                    return '';
                }

                return items.map((loopContext) => {
                    const isObject = typeof loopContext._this_ === 'object' && loopContext._this_ !== null;

                    if (isObject) {
                        Object.assign(loopContext, loopContext._this_);
                    }

                    return processContent(content, loopContext);
                }).join('');
            }
        );
    };

    const cleanWhitespace = (tmpl) => {
        return tmpl
            .replace(/\s*(\{\{#(?:if|unless|each)[^}]*\}\})\s*/g, '$1')
            .replace(/\s*(\{\{\/(?:if|unless|each)\}\})\s*/g, '$1')
            .replace(/\s*(\{\{(?:else|elseif)[^}]*\}\})\s*/g, '$1');
    };

    // --- 4. Ejecución ---
    let processedTemplate = preserveWhitespace ? template : cleanWhitespace(template);
    processedTemplate = processLoops(processedTemplate, data);
    return processContent(processedTemplate, data);
}

